// 1. Validar Authorization: Bearer <SYNC_SECRET>
const firstItem = $input.first().json;
const headers = firstItem.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const secret = ($env.SYNC_SECRET || '').trim();

if (!secret) {
  throw new Error('SYNC_SECRET no configurado en n8n');
}
if (!auth.startsWith('Bearer ') || auth.slice(7).trim() !== secret) {
  throw new Error('Unauthorized: Bearer token inválido');
}

// 2. Extraer y normalizar el body
let body = firstItem.body || firstItem;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { throw new Error('JSON inválido en el body'); }
}

const busquedas = Array.isArray(body.busquedas_makerworld)
  ? body.busquedas_makerworld
  : (Array.isArray(body) ? body : []);

if (busquedas.length === 0) {
  throw new Error('No se encontraron elementos en busquedas_makerworld');
}

const limitPerConcept = Math.min(Math.max(Number(body.limitPerConcept) || 3, 1), 10);

return [{
  json: {
    busquedas_makerworld: busquedas,
    limitPerConcept
  }
}];

// PASO 1: Buscar candidatos en MakerWorld (vía FlareSolverr) y filtrar licencias comerciales.
const inputData = $input.first().json;
const busquedas = inputData.busquedas_makerworld || [];
const TOP_N = inputData.limitPerConcept || 3;
const FLARESOLVERR_URL = 'http://flaresolverr:8191/v1';

const LICENSE_MAP = {
  'BY': 'CC-BY',
  'BY-SA': 'CC-BY-SA',
  'BY-NC': 'CC-BY-NC',
  'BY-NC-SA': 'CC-BY-NC',
  'BY-ND': 'CC-BY',
  'BY-NC-ND': 'CC-BY-NC',
  'CC0': 'CC0',
  'Standard Digital File License': 'commercial',
};
const RESELLABLE_LICENSES = new Set(['CC-BY', 'CC-BY-SA', 'CC0', 'commercial']);

const TITLE_PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*easy\s*(to\s*)?print(ing)?\b/gi,
  /\|?\s*no\s*supports?\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /\|?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
];

function cleanTitle(t) {
  if (!t) return 'Sin título';
  let out = String(t);
  for (const p of TITLE_PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—–-]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : 'Sin título';
}

let lastCookies = '';

async function flareGetJson(targetUrl, timeoutMs = 25000) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: FLARESOLVERR_URL,
    headers: { 'Content-Type': 'application/json' },
    body: {
      cmd: 'request.get',
      url: targetUrl,
      maxTimeout: timeoutMs
    },
    timeout: timeoutMs + 8000
  });
  const cookies = res?.solution?.cookies || [];
  if (cookies.length > 0) {
    lastCookies = cookies.map(c => `${c.name}=${c.value}`).join('; ');
  }
  const htmlStr = res?.solution?.response || '';
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;
  rawJson = rawJson.replace(/^<pre[^>]*>/i, '').replace(/<\/pre>.*$/is, '').replace(/<[^>]*>?/gm, '').trim();
  return JSON.parse(rawJson);
}

const seenExternalIds = new Set();
const selectedCandidates = [];
const conceptReports = [];

for (const concepto of busquedas) {
  const cid = concepto.id ?? 0;
  const nombreConcepto = concepto.nombre_concepto || '';
  const categoriaSugerida = concepto.categoria || 'Gadgets & Utilidades';
  const q1 = (concepto.query_principal_ingles || '').trim();
  const q2 = (concepto.query_alternativa_ingles || '').trim();

  const conceptHits = [];
  let usedFallback = false;
  let discardedByLicense = 0;

  const processHits = (hits, queryUsed) => {
    for (const d of (hits || [])) {
      if (conceptHits.length >= TOP_N) break;
      const extId = String(d.id ?? '');
      if (!extId || seenExternalIds.has(extId)) continue;

      const rawLicense = (d.license || '').trim();
      const licenseType = LICENSE_MAP[rawLicense] || 'unknown';

      if (!RESELLABLE_LICENSES.has(licenseType)) {
        discardedByLicense++;
        continue;
      }

      seenExternalIds.add(extId);
      const author = d.designCreator?.name || 'Unknown';
      const slug = d.slug || extId;

      conceptHits.push({
        externalId: extId,
        source: 'MAKERWORLD',
        sourceUrl: `https://makerworld.com/en/models/${slug}`,
        title: cleanTitle(d.titleTranslated || d.title),
        description: '',
        imageUrl: d.cover || d.coverPortrait || null,
        licenseType,
        rawLicense,
        licenseAttribution: `${author} — via MakerWorld`,
        category: categoriaSugerida,
        tags: Array.isArray(d.tags) ? d.tags.slice(0, 15) : [],
        trendScore: Math.round(d.hotScore ?? d.likeCount ?? 0),
        provider: 'LOCAL',
        __cookies: lastCookies,
        __concepto: {
          id: cid,
          nombre_concepto: nombreConcepto,
          categoria: categoriaSugerida,
          query_usada: queryUsed
        }
      });
    }
  };

  if (q1) {
    try {
      const searchUrl1 = `https://makerworld.com/api/v1/search-service/select/design2?orderBy=score&designType=0&isFromSearchList=false&limit=15&offset=0&keyword=${encodeURIComponent(q1)}`;
      const parsed1 = await flareGetJson.call(this, searchUrl1, 25000);
      processHits(parsed1.hits || [], q1);
    } catch (e) {
      console.log(`Error buscando query principal "${q1}":`, e.message);
    }
  }

  if (conceptHits.length < TOP_N && q2) {
    usedFallback = true;
    try {
      const searchUrl2 = `https://makerworld.com/api/v1/search-service/select/design2?orderBy=score&designType=0&isFromSearchList=false&limit=15&offset=0&keyword=${encodeURIComponent(q2)}`;
      const parsed2 = await flareGetJson.call(this, searchUrl2, 25000);
      processHits(parsed2.hits || [], q2);
    } catch (e) {
      console.log(`Error buscando query alternativa "${q2}":`, e.message);
    }
  }

  selectedCandidates.push(...conceptHits);
  conceptReports.push({
    id: cid,
    nombre_concepto: nombreConcepto,
    categoria: categoriaSugerida,
    query_principal: q1,
    query_alternativa: q2,
    usada_alternativa: usedFallback,
    seleccionados: conceptHits.length,
    descartados_licencia: discardedByLicense
  });
}

if (selectedCandidates.length === 0) {
  return [{
    json: {
      __noCandidates: true,
      conceptReports,
      conceptsProcessed: busquedas.length
    }
  }];
}

return selectedCandidates.map((cand, idx) => ({
  json: {
    ...cand,
    __conceptReports: idx === 0 ? conceptReports : undefined,
    __conceptsProcessed: idx === 0 ? busquedas.length : undefined
  }
}));

// PASO 2 (Por cada producto individual): Detalle MakerWorld (FlareSolverr) + Cálculo de Precios + Gemini Multimodal + Copy FB
const cand = $input.first().json;
if (cand.__noCandidates) {
  return [{ json: cand }];
}

const GEMINI_API_KEY = ($env.GEMINI_API_KEY || '').trim();
const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${GEMINI_API_KEY}`;
const FLARESOLVERR_URL = 'http://flaresolverr:8191/v1';
const flareUserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36';

const TITLE_PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*easy\s*(to\s*)?print(ing)?\b/gi,
  /\|?\s*no\s*supports?\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /\|?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
];

function cleanVariantName(t, idx) {
  if (!t) return `Variante ${idx + 1}`;
  let out = String(t);
  for (const p of TITLE_PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—–-]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : `Variante ${idx + 1}`;
}

const FILAMENT_PRICE_PER_KG = 400, WASTE_PCT = 5, KWH_PRICE = 4.5, WATTS = 100, MARGIN_PCT = 300;
function priceForPlates(plates) {
  const grams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
  const seconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
  const hours = seconds / 3600;
  if (grams <= 0 || hours <= 0) return null;
  const effectiveGrams = grams * (1 + WASTE_PCT / 100);
  const filament = (effectiveGrams / 1000) * FILAMENT_PRICE_PER_KG;
  const electricity = hours * (WATTS / 1000) * KWH_PRICE;
  const subtotal = filament + electricity;
  return {
    grams: Number(grams.toFixed(1)),
    hours: Number(hours.toFixed(2)),
    price: Math.round(subtotal * (1 + MARGIN_PCT / 100))
  };
}

const stripHtml = (html) => String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 2000);

let detJson = {};
let lastCookies = cand.__cookies || '';
try {
  const detailUrl = `https://makerworld.com/api/v1/design-service/design/${cand.externalId}`;
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: FLARESOLVERR_URL,
    headers: { 'Content-Type': 'application/json' },
    body: { cmd: 'request.get', url: detailUrl, maxTimeout: 25000 },
    timeout: 32000
  });
  const cookies = res?.solution?.cookies || [];
  if (cookies.length > 0) {
    lastCookies = cookies.map(c => `${c.name}=${c.value}`).join('; ');
  }
  const htmlStr = res?.solution?.response || '';
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;
  rawJson = rawJson.replace(/^<pre[^>]*>/i, '').replace(/<\/pre>.*$/is, '').replace(/<[^>]*>?/gm, '').trim();
  detJson = JSON.parse(rawJson);
} catch (detErr) {
  console.log(`Error obteniendo detalle de ${cand.externalId}:`, detErr.message);
}

const instances = detJson?.instances || [];
const designExtension = detJson?.designExtension || {};
const designPics = Array.isArray(designExtension?.design_pictures)
  ? designExtension.design_pictures.map(p => p.url).filter(Boolean)
  : [];
const cover = detJson?.cover || cand.imageUrl;
let images = cover ? [cover, ...designPics.filter(u => u !== cover)] : designPics;

const variantsRaw = instances.map((ins, i) => {
  const plates = (((ins.extention) || {}).modelInfo || {}).plates || [];
  const calc = priceForPlates(plates);
  if (!calc) return null;
  const insImg = (ins.extention && ins.extention.modelInfo && ins.extention.modelInfo.image) || ins.image || ins.cover || ins.picture;
  return {
    name: cleanVariantName(ins.title || ins.titleTranslated, i),
    grams: calc.grams,
    hours: calc.hours,
    price: calc.price,
    imageUrl: insImg || null
  };
}).filter(Boolean);

variantsRaw.forEach(v => {
  if (v.imageUrl && !images.includes(v.imageUrl)) {
    images.push(v.imageUrl);
  }
});

let variants = variantsRaw.sort((a, b) => a.price - b.price);
if (variants.length === 0) {
  variants = [{ name: 'Estándar', grams: 60, hours: 2.0, price: 145 }];
}

const priceFrom = variants[0].price;
const rawSummary = detJson?.summaryTranslated || detJson?.summary || '';

const p = {
  ...cand,
  description: stripHtml(rawSummary),
  descriptionHtml: rawSummary.slice(0, 2000),
  images: images.slice(0, 10),
  imageUrl: images[0] || cand.imageUrl,
  variants,
  priceFrom,
  price: priceFrom,
  meli_pictures: [],
  meli_variations: [],
  fb_post: '',
  __mainImgBase64: null,
  __mainImgMime: 'image/jpeg',
  __mainImgExt: 'jpg'
};

// Descargar imágenes (máx 2) para Gemini y Drive
const base64Images = [];
const imgUrls = p.images.length > 0 ? p.images : (p.imageUrl ? [p.imageUrl] : []);
for (let idx = 0; idx < Math.min(imgUrls.length, 6); idx++) {
  const u = imgUrls[idx];
  if (u) p.meli_pictures.push({ source: u });
}

for (let idx = 0; idx < Math.min(imgUrls.length, 2); idx++) {
  const imgUrl = imgUrls[idx];
  if (!imgUrl) continue;
  try {
    const imgBuffer = await this.helpers.httpRequest({
      method: 'GET',
      url: imgUrl,
      encoding: null,
      responseType: 'arraybuffer',
      timeout: 5000,
      headers: {
        'User-Agent': flareUserAgent,
        'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
        'Referer': 'https://makerworld.com/',
        'Cookie': lastCookies
      }
    });
    if (imgBuffer && imgBuffer.length > 500) {
      let mimeType = null;
      let ext = 'jpg';
      const header = Buffer.from(imgBuffer).slice(0, 4).toString('hex').toUpperCase();
      if (header.startsWith('89504E47')) { mimeType = 'image/png'; ext = 'png'; }
      else if (header.startsWith('52494646')) { mimeType = 'image/webp'; ext = 'webp'; }
      else if (header.startsWith('FFD8FF')) { mimeType = 'image/jpeg'; ext = 'jpg'; }
      else if (header.startsWith('47494638')) { mimeType = 'image/gif'; ext = 'gif'; }

      const b64Str = Buffer.from(imgBuffer).toString('base64');
      if (!p.__mainImgBase64) {
        p.__mainImgBase64 = b64Str;
        p.__mainImgMime = mimeType || 'image/jpeg';
        p.__mainImgExt = ext;
      }
      if (mimeType && mimeType !== 'image/gif') {
        base64Images.push({ mimeType, data: b64Str });
      }
    }
  } catch {}
}

// Enriquecimiento con Gemini
if (GEMINI_API_KEY) {
  const variantsInfo = p.variants.map((v, i) => `[${i + 1}] ${v.name} (${v.grams}g, $${v.price})`).join(', ');
  const prompt = `Analiza el siguiente producto para publicarlo en nuestra tienda "El Rincón de Brandy", en Mercado Libre y en redes sociales (Facebook/Instagram):
Concepto / Línea buscada: ${p.__concepto?.nombre_concepto || ''}
Categoría objetivo: ${p.__concepto?.categoria || ''}
Título Original: ${p.title}
Descripción original: ${p.description?.slice(0, 500)}
Precio base: $${p.price} MXN
Variantes Físicas Disponibles (nombre, peso, precio): ${variantsInfo}

REGLA CRÍTICA DE NEGOCIO:
Eres una tienda online que vende el producto FÍSICO ya fabricado. El cliente es un comprador normal (no sabe de impresión 3D).
ESTRICTAMENTE PROHIBIDO usar palabras como "impresión 3D", "print in place", "sin soportes", "STL", "filamento", "maker", "PLA", "Bambu", "A1 Mini".
Adapta el título y la descripción al concepto comercial ("${p.__concepto?.nombre_concepto || ''}") destacando su beneficio práctico, diseño o funcionalidad.

REGLA SOBRE COMPONENTES ELECTRÓNICOS / ILUMINACIÓN:
Si el producto es una carcasa, lámpara o soporte que requiere LED/focos/electrónica externa, aclara brevemente en la descripción que incluye la estructura física lista para usar.

Devuelve ÚNICAMENTE un JSON válido con esta estructura exacta:
{
  "title": "Nuevo título altamente comercial en español, corto y atractivo (máx 58 caracteres)",
  "description": "Descripción persuasiva enfocada en beneficios y usos del producto físico (máx 150 caracteres).",
  "category": "${p.__concepto?.categoria || 'Gadgets & Utilidades'}",
  "hashtags": ["tag1", "tag2", "tag3"],
  "variants": [
    {
      "name": "Nombre comercial en español (ej. Estándar, Compacto, Grande, Completo. SIN términos 3D)",
      "price": 100
    }
  ],
  "fb_post": "Copy completo para Facebook/Instagram de 'El Rincón de Brandy' promocionando este producto físico (máx 3 párrafos cortos, tono entusiasta y persuasivo, incluye emojis, menciona el precio desde $${p.price} MXN, invita a comprarlo en https://shongyi.com/bazar y añade 3-4 hashtags al final)."
}
Nota: El array 'variants' debe tener exactamente ${p.variants.length} elementos en el mismo orden.`;

  const parts = [{ text: prompt }];
  for (const img of base64Images) {
    parts.push({ inlineData: { mimeType: img.mimeType, data: img.data } });
  }

  try {
    const gRes = await this.helpers.httpRequest({
      method: 'POST',
      url: GEMINI_URL,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts }] },
      timeout: 20000
    });
    const rawText = gRes?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const jsonMatch = rawText.match(/\{.*\}/s);
    if (jsonMatch) {
      const aiData = JSON.parse(jsonMatch[0]);
      if (aiData.title) p.title = String(aiData.title).trim();
      if (aiData.description) p.description = String(aiData.description).trim();
      if (aiData.category) p.category = String(aiData.category).trim();
      if (Array.isArray(aiData.hashtags)) p.tags = aiData.hashtags;
      if (aiData.fb_post) p.fb_post = String(aiData.fb_post).trim();

      if (Array.isArray(aiData.variants) && aiData.variants.length === p.variants.length) {
        p.meli_variations = [];
        for (let j = 0; j < p.variants.length; j++) {
          const vName = typeof aiData.variants[j] === 'string'
            ? aiData.variants[j]
            : (aiData.variants[j]?.name || p.variants[j].name);
          p.variants[j].name = vName;
          p.meli_variations.push({
            attribute_combinations: [
              { id: 'TAMAÑO', name: 'Tamaño', value_name: vName }
            ],
            price: p.variants[j].price,
            available_quantity: 5,
            picture_ids: p.meli_pictures.length > 0 ? [p.meli_pictures[0].source] : []
          });
        }
      }
    }
  } catch (gemErr) {
    console.log(`Error Gemini en producto ${p.externalId}:`, gemErr.message);
  }
}

if (!p.fb_post) {
  p.fb_post = `✨ ¡Nuevo en El Rincón de Brandy! ✨\n\n${p.title}\n${p.description}\n\n💰 Desde $${p.price} MXN\n🛒 Pídelo en línea en: https://shongyi.com/bazar\n\n#ElRinconDeBrandy #Diseño #Gadgets`;
}

if (!p.meli_variations || p.meli_variations.length === 0) {
  p.meli_variations = [{
    attribute_combinations: [
      { id: 'TAMAÑO', name: 'Tamaño', value_name: p.variants[0]?.name || 'Estándar' }
    ],
    price: p.price || 145,
    available_quantity: 5,
    picture_ids: p.meli_pictures.length > 0 ? [p.meli_pictures[0].source] : []
  }];
}

return [{ json: p }];

// PASO 3 y 4: Al terminar el loop de productos, sincronizar todos en Bazar D1, publicar en Mercado Libre y preparar binarios para Google Drive
const allItems = $input.all().map(i => i.json);
const firstSearchNode = $('1. Buscar en MakerWorld y Filtrar Licencias').first().json;
const conceptReports = firstSearchNode.__conceptReports || firstSearchNode.conceptReports || [];
const conceptsProcessed = firstSearchNode.__conceptsProcessed || firstSearchNode.conceptsProcessed || 1;

const enrichedProducts = allItems.filter(p => p && p.externalId && !p.__noCandidates);

const rawTaskmanUrl = ($env.TASKMAN_API_URL || '').replace(/\/$/, '');
const TASKMAN_API_URL = (!rawTaskmanUrl || rawTaskmanUrl.includes('host.docker.internal') || rawTaskmanUrl.includes('172.17.0.1'))
  ? 'http://task_backend:3000'
  : rawTaskmanUrl;
const SYNC_SECRET = ($env.SYNC_SECRET || '').trim();

let bazarSyncResult = { created: 0, updated: 0, skipped: 0, errors: [] };
let meliAccessToken = null;

if (enrichedProducts.length > 0) {
  try {
    const cleanForSync = enrichedProducts.map(({ __mainImgBase64, __mainImgMime, __mainImgExt, __cookies, __conceptReports, __conceptsProcessed, fb_post, ...rest }) => rest);
    const syncRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `${TASKMAN_API_URL}/api/products/sync`,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${SYNC_SECRET}`
      },
      body: { products: cleanForSync },
      timeout: 45000
    });
    if (syncRes?.results) bazarSyncResult = syncRes.results;
    if (syncRes?.meliAccessToken) meliAccessToken = syncRes.meliAccessToken;
  } catch (syncErr) {
    bazarSyncResult.errors.push({ error: syncErr.message });
  }
}

// Publicar en Mercado Libre
const meliResults = [];
if (meliAccessToken && enrichedProducts.length > 0) {
  for (const prod of enrichedProducts) {
    const cleanMeliTitle = prod.title.substring(0, 60);
    const meliPayload = {
      title: cleanMeliTitle,
      family_name: cleanMeliTitle,
      category_id: 'MLM3530',
      price: prod.variants && prod.variants.length > 0 ? prod.variants[0].price : (prod.price || 145),
      currency_id: 'MXN',
      available_quantity: 5,
      buying_mode: 'buy_it_now',
      condition: 'new',
      listing_type_id: 'gold_special',
      pictures: prod.meli_pictures || [],
      variations: prod.meli_variations || []
    };
    if (meliPayload.variations.length === 0) {
      delete meliPayload.variations;
    }

    try {
      const mRes = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.mercadolibre.com/items',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${meliAccessToken}`
        },
        body: meliPayload,
        timeout: 20000
      });
      meliResults.push({
        externalId: prod.externalId,
        title: prod.title,
        status: 'published',
        meliId: mRes?.id || null,
        permalink: mRes?.permalink || null
      });
    } catch (mErr) {
      let errDetail = mErr.message;
      try {
        if (mErr.response?.data) errDetail = JSON.stringify(mErr.response.data);
      } catch {}
      meliResults.push({
        externalId: prod.externalId,
        title: prod.title,
        status: 'error',
        error: errDetail
      });
    }
  }
} else if (!meliAccessToken) {
  for (const prod of enrichedProducts) {
    meliResults.push({
      externalId: prod.externalId,
      title: prod.title,
      status: 'skipped_no_token',
      error: 'Token de Mercado Libre no disponible o expirado. Reconecta en /api/meli/auth'
    });
  }
}

// Preparar archivos para subir en lote a la carpeta de posts de Google Drive
const driveFilesToCreate = [];
for (const prod of enrichedProducts) {
  const safeSlug = prod.title
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '_')
    .slice(0, 45) || `Producto_${prod.externalId}`;

  const baseName = `${prod.externalId}_${safeSlug}`;
  const txtContent = [
    `PRODUCTO: ${prod.title}`,
    `CONCEPTO: ${prod.__concepto?.nombre_concepto || ''}`,
    `CATEGORÍA: ${prod.category || ''}`,
    `PRECIO DESDE: $${prod.price} MXN`,
    `TIENDA: https://shongyi.com/bazar`,
    `IMAGEN ORIGINAL: ${prod.imageUrl || ''}`,
    ``,
    `--- TEXTO DEL POST PARA FACEBOOK / INSTAGRAM ---`,
    prod.fb_post
  ].join('\n');

  driveFilesToCreate.push({
    externalId: prod.externalId,
    productTitle: prod.title,
    fileType: 'txt',
    fileName: `${baseName}_POST.txt`,
    mimeType: 'text/plain',
    base64Data: Buffer.from(txtContent, 'utf-8').toString('base64')
  });

  if (prod.__mainImgBase64) {
    driveFilesToCreate.push({
      externalId: prod.externalId,
      productTitle: prod.title,
      fileType: 'image',
      fileName: `${baseName}_IMAGEN.${prod.__mainImgExt || 'jpg'}`,
      mimeType: prod.__mainImgMime || 'image/jpeg',
      base64Data: prod.__mainImgBase64
    });
  }
}

return [{
  json: {
    success: true,
    summary: {
      conceptsProcessed,
      candidatesFound: enrichedProducts.length,
      enrichedCount: enrichedProducts.length,
      bazar: bazarSyncResult,
      meliConnected: Boolean(meliAccessToken),
      meliPublished: meliResults.filter(r => r.status === 'published').length,
      meliErrors: meliResults.filter(r => r.status !== 'published').length,
      driveFilesPrepared: driveFilesToCreate.length
    },
    conceptReports,
    meliResults,
    driveFilesToCreate,
    products: enrichedProducts.map(p => ({
      externalId: p.externalId,
      title: p.title,
      description: p.description,
      category: p.category,
      price: p.price,
      licenseType: p.licenseType,
      imageUrl: p.imageUrl,
      sourceUrl: p.sourceUrl,
      variantsCount: (p.variants || []).length,
      concepto: p.__concepto?.nombre_concepto,
      fb_post: p.fb_post
    }))
  }
}];

const first = $input.first().json;
const files = first.driveFilesToCreate || [];

if (files.length === 0) {
  return [{ json: { __skipDrive: true } }];
}

return files.map(f => ({
  json: {
    __skipDrive: false,
    externalId: f.externalId,
    productTitle: f.productTitle,
    fileType: f.fileType,
    fileName: f.fileName
  },
  binary: {
    data: {
      data: f.base64Data,
      mimeType: f.mimeType,
      fileName: f.fileName
    }
  }
}));

const base = $('3. Publicar en Bazar y Mercado Libre').first().json;
const driveItems = $input.all().map(i => i.json).filter(x => x && x.id && !x.__skipDrive);

const { driveFilesToCreate, ...cleanBase } = base;
cleanBase.summary.driveUploadedCount = driveItems.length;
cleanBase.summary.driveFolderId = '1YQMXeP7h3s53_8RxPs4C7lAK4XxwU_Do';
cleanBase.summary.driveFolderUrl = 'https://drive.google.com/drive/folders/1YQMXeP7h3s53_8RxPs4C7lAK4XxwU_Do';
cleanBase.driveFiles = driveItems.map(d => ({
  id: d.id,
  name: d.name,
  mimeType: d.mimeType,
  webViewLink: d.webViewLink || `https://drive.google.com/file/d/${d.id}/view`
}));

return [{ json: cleanBase }];
